}

callisto_build_local_wasm() (
  local workspace="$1" destination="$2" build_dir artifact
  # The crate is an rlib by default. Request the plugin explicitly and use a
  # fresh target directory so an earlier checkout's artifact cannot be copied.
  build_dir="$(mktemp -d "${RUNNER_TEMP:-${TMPDIR:-/tmp}}/callisto-wasm-build.XXXXXX")" || return 1
  trap 'rm -rf -- "$build_dir"' EXIT
  cargo rustc --manifest-path "$workspace/Cargo.toml" -p callisto-moon --lib \
    --target wasm32-wasip1 --features pdk --crate-type cdylib --release --target-dir "$build_dir" || {
    callisto_error "could not build the local Callisto WASM plugin"
    return 1
  }
  artifact="$build_dir/wasm32-wasip1/release/callisto_moon.wasm"
  if [[ ! -f "$artifact" ]]; then
    callisto_error "local WASM build did not produce callisto_moon.wasm"
    return 1
  fi
  cp "$artifact" "$destination"
)

callisto_install_wasm() {
  local source="$1" tag="$2" asset="$3" destination="$4" workspace="$5"
  mkdir -p "$(dirname "$destination")"
  case "$source" in
    local)
      callisto_require_local_workspace "$workspace" || return 1
      callisto_build_local_wasm "$workspace" "$destination"
      ;;
    release|auto)
      curl --fail --silent --show-error --location \
        "${CALLISTO_RELEASES_URL}/${tag}/${asset}" --output "$destination"
      ;;
    registry)
      callisto_error "source=registry does not provide the callisto-moon WASM artifact"
      ;;
    *) callisto_error "internal error: unsupported source '$source'" ;;
  esac
}

