impl<W: ReleaseReceiptWriter> ReleaseReceiptStore<W> {
    pub fn with_writer(path: impl Into<PathBuf>, writer: W) -> Self {
        Self {
            path: path.into(),
            writer,
        }
    }

    pub fn path(&self) -> &Path {
        &self.path
    }

    pub fn save(
        &self,
        intent: &ReleaseIntent,
        expectations: &ObservationExpectations,
        receipt: &CompleteObservationReceipt,
        permit: &ApplyPermit,
    ) -> Result<(), GraphError> {
        receipt
            .validate_for_intent(intent, expectations)
            .map_err(|source| GraphError::ReleaseInvariant {
                detail: format!("refused to persist a non-exact observation receipt: {source}"),
            })?;
        let content = serde_json::to_string_pretty(receipt)
            .expect("closed observation receipt serialization is infallible")
            + "\n";
        self.writer
            .write(&self.path, &content, permit)
            .map_err(|error| GraphError::ReleaseStateWrite {
                path: self.path.clone(),
                message: error.to_string(),
            })
    }
}

